package imagesearch

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"unicode/utf8"

	"github.com/anthnel/devdesk/internal/oci"
)

const (
	// CatalogMaxPages is the number of catalog pages followed per walk.
	CatalogMaxPages = 10
	// CatalogPageSize is the number of names asked per page (?n=).
	CatalogPageSize = 1000
	// CatalogMaxRows is the number of rows one registry may show.
	CatalogMaxRows = 100
	// CatalogMinQueryRunes is the shortest query that walks a catalog.
	CatalogMinQueryRunes = 2
)

// CatalogLister walks a registry's catalog; oci.ListCatalogContext in production.
type CatalogLister func(ctx context.Context, apiURL, username, password string,
	maxPages, pageSize int) (names []string, truncated bool, err error)

// CatalogSearcher searches a private registry by walking /v2/_catalog and
// filtering names client-side; the query is never sent to the registry.
type CatalogSearcher struct {
	// List overrides oci.ListCatalogContext when set (tests).
	List CatalogLister
}

// Search implements Searcher.
func (c CatalogSearcher) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
	text := strings.TrimSpace(q.Text)
	if utf8.RuneCountInString(text) < CatalogMinQueryRunes {
		return nil, false, ErrQueryTooShort
	}
	list := c.List
	if list == nil {
		list = oci.ListCatalogContext
	}
	names, truncated, err := list(ctx, t.APIURL, t.Username, t.Password, CatalogMaxPages, CatalogPageSize)
	if err != nil {
		return nil, false, err
	}
	if len(names) == 0 {
		return nil, truncated, nil
	}
	prefix := strings.Trim(t.RepoPrefix, "/")
	needle := strings.ToLower(text)
	var all []Image
	sawPrefix := false
	for _, name := range names {
		rest := name
		if prefix != "" {
			var ok bool
			if rest, ok = strings.CutPrefix(name, prefix+"/"); !ok {
				continue
			}
			sawPrefix = true
		}
		if !validRepoPath(name) {
			continue
		}
		if strings.Contains(strings.ToLower(rest), needle) {
			all = append(all, Image{EntryKey: t.EntryKey, Name: rest, Repo: name})
		}
	}
	if prefix != "" && !sawPrefix {
		if truncated {
			return nil, true, nil
		}
		return nil, false, fmt.Errorf("%w (prefix %q)", ErrPrefixNotInCatalog, prefix)
	}
	slices.SortStableFunc(all, func(a, b Image) int {
		if d := MatchTier(text, a.Name) - MatchTier(text, b.Name); d != 0 {
			return d
		}
		if d := strings.Compare(strings.ToLower(a.Name), strings.ToLower(b.Name)); d != 0 {
			return d
		}
		return strings.Compare(a.Repo, b.Repo)
	})
	limit := CatalogMaxRows
	if q.Limit > 0 && q.Limit < limit {
		limit = q.Limit
	}
	cut := len(all) > limit
	if cut {
		all = all[:limit]
	}
	return all, truncated || cut, nil
}

// Package imagesearch defines the types and the interface of an image search
// against one registry: what to search (Query), where (Target) and what comes
// back (Image). It is pure Go, with no UI and no network code of its own; the
// adapters that talk to a registry implement Searcher elsewhere.
//
// Anonymous Docker Hub search is not covered here (see IS-02).
package imagesearch

import "context"

// Target describes the registry entry a search runs against.
type Target struct {
	EntryKey    string
	Alias       string
	RegistryURL string
	APIURL      string
	RepoPrefix  string
	// Username and Password are empty for an anonymous entry (D12).
	Username string
	Password string
}

// Query is a search request. Limit 0 means the adapter's default.
type Query struct {
	Text  string
	Limit int
}

// Image is one search result.
type Image struct {
	EntryKey string
	Name     string
	// Repo is the final repository path, with the prefix and the library/
	// namespace applied exactly once (D39).
	Repo        string
	Description string
	Stars       int
	// HasStars tells whether Stars is meaningful for this registry.
	HasStars bool
	Official bool
}

// Searcher searches one registry. partial is true when the result is cut short
// (limit, deadline or a page that failed) but still usable.
type Searcher interface {
	Search(ctx context.Context, t Target, q Query) (images []Image, partial bool, err error)
}

// SearcherFunc adapts a function to the Searcher interface.
type SearcherFunc func(ctx context.Context, t Target, q Query) ([]Image, bool, error)

// Search calls f.
func (f SearcherFunc) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
	return f(ctx, t, q)
}

