199	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
200		if msg.Gen != b.gen {
201			return false
202		}
203		if b.pendingSearches > 0 {
204			b.pendingSearches--
205		}
206		oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
207		if b.outcomes == nil {
208			b.outcomes = map[string]imagesearch.Outcome{}
209		}
210		b.outcomes[msg.EntryKey] = oc
211		if oc.Verdict == imagesearch.VerdictOK {
212			for _, img := range msg.Images {
213				img.EntryKey = msg.EntryKey
214				b.images = append(b.images, img)
215			}
216		}
217		b.rebuildSearchTable()
218		return true
219	}
