221	// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
222	// back to the form; esc acts in order: the filter bar while it is open, then a
223	// confirmed query, then it cancels the lot and goes back to the form (which
224	// keeps the typed name and the selection). The lot's late answers are no
225	// longer wanted and are dropped
226	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
227	// nothing: a row has no action yet; → opens the row's tags.
228	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
229		if b.searchTable.InEditMode() {
230			return b, b.searchTable.Update(msg)
231		}
232		switch msg.String() {
233		case ".":
234			b.cycleSearchSort()
235			return b, nil
236		case "r":
237			b.cycleSearchRegistryFilter()
238			return b, nil
239		case "right":
240			return b.openSelectedImageTags()
241		case "esc":
242			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
243				// The cursor stays on the selected row once the filter is gone.
244				prev, had := b.searchTable.Selected()
245				bar.ClearSearch()
246				b.searchTable.SetItems(b.searchTable.Items())
247				b.reselect(prev, had)
248				return b, nil
249			}
250			return b.backToForm()
251		case "left":
252			return b.backToForm()
253		case "enter":
254			return b, nil
255		}
256		return b, b.searchTable.Update(msg)
257	}
