259	// backToForm cancels the lot and returns to the form, which keeps the typed
260	// name and the selection. Late answers of the lot are dropped.
261	func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
262		b.abandonLot()
263		b.state = browserStateInput
264		b.searchTable.Blur()
265		b.updateFocus()
